INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob der Einkaufspreis allein den Verkaufspreis bestimmt?', 2, '[{"text": "Nein", "correct": true, "because": "Aufschläge und Rabatte zählen"}, {"text": "Ja", "correct": false, "because": "Kosten und Gewinn fehlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, um den Verkaufspreis einer IT-Lösung festzulegen?', 3, '[{"text": "Kosten plus Gewinnaufschlag", "correct": true, "because": "Bildet realistischen Preis"}, {"text": "Nur Einkaufspreis", "correct": false, "because": "Ignoriert Zusatzkosten"}, {"text": "Markttrend", "correct": false, "because": "Nur ein Einflussfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kosten muss ich bei der Preisbildung für Hardware berücksichtigen?', 5, '[{"text": "Einkaufspreis", "correct": true, "because": "Basis der Kalkulation"}, {"text": "Versandkosten", "correct": true, "because": "Erhöhen Gesamtkosten"}, {"text": "Marketingbudget", "correct": false, "because": "Indirekt relevant"}, {"text": "Büromiete", "correct": false, "because": "Nicht direkt zugeordnet"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rabatte senken den Verkaufspreis. b) Skonto erhöht die Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skonto senkt Einkaufskosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich den Preis für eine Softwarelizenz kalkuliere?', 4, '[{"text": "Lizenzgebühren", "correct": false, "because": "Grundkosten"}, {"text": "Supportkosten", "correct": false, "because": "Teil des Angebots"}, {"text": "Verpackungsdesign", "correct": true, "because": "Irrelevant für Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Verkaufspreis immer den Marktpreis übersteigen muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann wettbewerbsfähig niedriger sein"}, {"text": "Ja", "correct": false, "because": "Flexibel gestaltbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um den Preis eines IT-Dienstes zu bestimmen?', 3, '[{"text": "Zuschlagskalkulation", "correct": true, "because": "Addiert Gewinn auf Kosten"}, {"text": "Nur Stundensatz", "correct": false, "because": "Ignoriert Zusatzkosten"}, {"text": "Marktvergleich", "correct": false, "because": "Nur Orientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen den Verkaufspreis eines Servers?', 5, '[{"text": "Einkaufspreis", "correct": true, "because": "Basis der Kosten"}, {"text": "Handlungskosten", "correct": true, "because": "Lagerung und Vertrieb"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Kein Kostenfaktor"}, {"text": "Büroausstattung", "correct": false, "because": "Indirekt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) ein Rabatt den Gewinn senkt und b) Skonto den Verkaufspreis erhöht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skonto wirkt beim Einkauf"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um den Preis einer Cloud-Lösung zu kalkulieren?', 4, '[{"text": "Nutzungsgebühren", "correct": false, "because": "Grundkosten"}, {"text": "Supportaufschlag", "correct": false, "because": "Teil des Angebots"}, {"text": "Firmenlogo", "correct": true, "because": "Kein Kostenfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Gewinnaufschlag immer fix?', 2, '[{"text": "Nein", "correct": true, "because": "Kann je nach Markt variieren"}, {"text": "Ja", "correct": false, "because": "Flexibel anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten fließen in den Preis eines Netzwerks ein?', 4, '[{"text": "Materialkosten", "correct": true, "because": "Hardware und Kabel"}, {"text": "Personalkosten", "correct": true, "because": "Installation und Wartung"}, {"text": "Kundendienstzeiten", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass der Listenpreis immer der Endpreis ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Rabatte und Skonti ändern ihn"}, {"text": "Ja", "correct": false, "because": "Endpreis ist verhandelbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich den Preis für eine IT-Lösung festlege?', 3, '[{"text": "Kostenabdeckung plus Gewinn", "correct": true, "because": "Sichert Rentabilität"}, {"text": "Maximale Rabatte", "correct": false, "because": "Kann Gewinn schmälern"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Kein Preisfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Handlungskosten erhöhen den Verkaufspreis. b) Skonto wirkt auf den Einkaufspreis.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Beide beeinflussen Kalkulation"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode hilft mir, den Preis für eine Dienstleistung zu bestimmen?', 4, '[{"text": "Stundensatz plus Zuschlag", "correct": true, "because": "Berücksichtigt Aufwand und Gewinn"}, {"text": "Nur Materialkosten", "correct": false, "because": "Ignoriert Arbeitszeit"}, {"text": "Marktpreis", "correct": false, "because": "Nur Orientierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Rabatte den Einkaufspreis beeinflussen?', 2, '[{"text": "Nein", "correct": true, "because": "Rabatte wirken auf Verkaufspreis"}, {"text": "Ja", "correct": false, "because": "Einkaufspreis bleibt gleich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen den Preis einer Hardware-Lösung realistisch?', 5, '[{"text": "Einkaufspreis", "correct": true, "because": "Basis der Kosten"}, {"text": "Vertriebskosten", "correct": true, "because": "Aufwand für Verkauf"}, {"text": "Kundenzufriedenheit", "correct": false, "because": "Indirekter Einfluss"}, {"text": "Bürogestaltung", "correct": false, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist der Nettopreis immer ohne Rabatte?', 2, '[{"text": "Nein", "correct": true, "because": "Rabatte können enthalten sein"}, {"text": "Ja", "correct": false, "because": "Nettopreis ist verhandelbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart beeinflusst den Preis eines IT-Systems direkt?', 4, '[{"text": "Bezugskosten", "correct": true, "because": "Einkauf und Transport"}, {"text": "Werbekosten", "correct": false, "because": "Indirekt relevant"}, {"text": "Reisekosten", "correct": false, "because": "Nicht produktspezifisch"}]');
